WITH flattened_attrs AS (SELECT id, service, host, level, payload_json, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['trace'], 'unknown') AS trace_or_default, context['trace'] AS trace, SIZE(context) AS num_context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs WHERE service IN ('billing', 'search')) SELECT *, LEAD(num_context) OVER w_recent AS next_num_context, LAG(num_context) OVER w_recent AS prev_num_context, ROW_NUMBER() OVER w_recent AS event_seq FROM flattened_attrs WINDOW w_recent AS (PARTITION BY host ORDER BY num_context ASC, id ASC)
